//! Version-1 operating-day demonstration. Weighted destination queues, fixed 48 km/h and 0.1-minute ticks.
use crate::{editor_support::*,value::Value as V,legacy::{self,add}};
fn queue_key(service:&V,dir:f64,station:&V)->String{format!("{}|{}|{}",service.text(),dir,jsstring(station))}
fn open(l:&V,minute:f64)->bool{let m=minute.rem_euclid(1440.0);m>=if has(l,"open"){l.num("open")}else{0.0}&&m<if has(l,"close"){l.num("close")}else{1440.0}}
fn groups(s:&V,metrics:&V)->V{let mut rows:Vec<V>=vec![];let mut indices=std::collections::HashMap::new();for flow in metrics.get("flows").array(){let mut from=flow.get("from").clone();let mut current=V::Missing;let daily=if has(flow,"demandTrips")&&!matches!(flow.get("demandTrips"),V::Null){flow.num("demandTrips")}else{flow.num("trips")};let mut pieces=vec![];for e in flow.get("path").get("edges").array(){let l=legacy::line(s,e.get("service"));if !l.truth(){continue;}let ix=l.get("trackIds").array().iter().enumerate().position(|(i,id)|eq(id,e.get("track"))&&((eq(&l.get("stops").array()[i],&from)&&eq(&l.get("stops").array()[i+1],e.get("to")))||(eq(&l.get("stops").array()[i+1],&from)&&eq(&l.get("stops").array()[i],e.get("to")))));let dir=if ix.is_some_and(|i|eq(&l.get("stops").array()[i],&from)){1.0}else{-1.0};if !current.truth()||!eq(current.get("service"),l.get("id"))||current.num("dir")!=dir{if current.truth(){pieces.push(current);}current=obj(&[("service",l.get("id").clone()),("dir",n(dir)),("from",from.clone()),("to",e.get("to").clone()),("daily",n(daily))]);}else{current.set("to",e.get("to").clone());}from=e.get("to").clone();}if current.truth(){pieces.push(current);}for g in pieces{if eq(g.get("from"),g.get("to")){continue;}let key=format!("{}|{}",queue_key(g.get("service"),g.num("dir"),g.get("from")),jsstring(g.get("to")));if let Some(&ix)=indices.get(&key){add(&mut rows[ix],"daily",g.num("daily"));}else{indices.insert(key,rows.len());rows.push(g);}}}arr(rows)}
fn create(s:&V,metrics:&V,start:f64)->V{create_groups(s,groups(s,metrics),start)}
fn create_groups(s:&V,groups:V,start:f64)->V{let mut rt=obj(&[("minute",n(start-30.0)),("start",n(start-30.0)),("nextId",n(1.0)),("trains",arr(vec![])),("departures",obj(&[])),("blocks",obj(&[])),("queues",obj(&[])),("groups",groups),("boarded",n(0.0)),("alighted",n(0.0)),("generated",n(0.0)),("dispatched",n(0.0)),("waitEvents",n(0.0)),("elapsed",n(0.0)),("events",arr(vec![]))]);for(i,l)in s.get("services").array().iter().enumerate(){for dir in [1.0,-1.0]{rt.get_mut("departures").set(&format!("{}|{}",l.get("id").text(),dir),obj(&[("next",n(start-30.0+(i%5)as f64*0.45+if dir==-1.0{legacy::headway(s,l)/2.0}else{0.0})),("count",n(0.0))]));}}advance(&mut rt,s,30.0);rt}
fn peak(minute:f64)->f64{let h=(minute/60.0)%24.0;if h<6.0{0.02}else if h<7.0{0.07}else if h<9.0{0.18}else if h<10.0{0.1}else if h<16.0{0.035}else if h<19.0{0.13}else if h<22.0{0.045}else{0.015}}
fn board(rt:&mut V,t:&mut V){let key=queue_key(t.get("service"),t.num("dir"),&t.get("stops").array()[t.num("index")as usize]);let mut rows=rt.get("queues").get(&key).entries().to_vec();rows.sort_by_key(|(id,_)|id.parse::<usize>().unwrap_or(usize::MAX));let mut left=t.num("capacity")-t.num("onboard");for(id,count)in rows{let take=left.min(count.n());if take<=0.0{continue;}add(t.get_mut("passengers"),&id,take);add(t,"onboard",take);add(rt,"boarded",take);rt.get_mut("queues").get_mut(&key).set(&id,n(count.n()-take));left-=take;if left<1e-8{break;}}}
fn tick(rt:&mut V,s:&V,dt:f64){add(rt,"minute",dt);add(rt,"elapsed",dt);let now=rt.num("minute");for g in rt.get("groups").array().to_vec(){let l=legacy::line(s,g.get("service"));if !l.truth()||!open(l,now){continue;}let amount=g.num("daily")*peak(now)/60.0*dt;let key=queue_key(g.get("service"),g.num("dir"),g.get("from"));add(rt.get_mut("queues").get_mut(&key),&jsstring(g.get("to")),amount);add(rt,"generated",amount);}
    for l in s.get("services").array(){for dir in [1.0,-1.0]{let key=format!("{}|{}",l.get("id").text(),dir);let d=rt.get("departures").get(&key).clone();if !d.truth(){continue;}if now+1e-8>=d.num("next"){if open(l,now){let stops=l.get("stops").array();let looped=eq(stops.first().unwrap(),stops.last().unwrap());let fleet=((legacy::route_time(s,l)+1.0)/legacy::headway(s,l)-1e-8).ceil();let active=rt.get("trains").array().iter().filter(|t|eq(t.get("service"),l.get("id"))&&t.get("status").text()!="finished").count()as f64;if !(looped&&d.num("count")>=fleet)&&!(l.get("fleet").truth()&&active>=l.num("fleet")){let id=format!("T{:03}",rt.num("nextId")as usize);add(rt,"nextId",1.0);rt.get_mut("trains").array_mut().push(obj(&[("id",text(&id)),("service",l.get("id").clone()),("dir",n(dir)),("stops",l.get("stops").clone()),("trackIds",l.get("trackIds").clone()),("index",n(if dir==1.0{0.0}else{stops.len()as f64-1.0})),("status",text("dwell")),("ready",n(now+0.6)),("onboard",n(0.0)),("capacity",n(legacy::capacity(l))),("passengers",obj(&[])),("progress",n(0.0)),("loop",boolean(looped)),("departedAt",V::Null),("arriveAt",V::Null),("segment",V::Null)]));add(rt.get_mut("departures").get_mut(&key),"count",1.0);add(rt,"dispatched",1.0);}}rt.get_mut("departures").get_mut(&key).set("next",n(d.num("next")+legacy::headway(s,l)));}}}
    let mut trains=rt.get("trains").array().to_vec();for t in &mut trains{let l=legacy::line(s,t.get("service"));if !l.truth(){t.set("status",text("finished"));continue;}if t.get("status").text()=="moving"{let progress=((now-t.num("departedAt"))/(t.num("arriveAt")-t.num("departedAt"))).min(1.0);t.set("progress",n(progress));if progress>=1.0-1e-8{let dir=t.num("dir");add(t,"index",dir);t.set("status",text("dwell"));t.set("ready",n(now+0.6));t.set("progress",n(0.0));let dest=jsstring(&t.get("stops").array()[t.num("index")as usize]);let amount=t.get("passengers").zero(&dest);add(t,"onboard",-amount);add(rt,"alighted",amount);del(t.get_mut("passengers"),&dest);let terminal=if t.num("dir")==1.0{t.num("index")as usize==t.get("stops").array().len()-1}else{t.num("index")==0.0};if terminal{if t.get("loop").truth()&&open(l,now){t.set("index",n(if t.num("dir")==1.0{0.0}else{t.get("stops").array().len()as f64-1.0}));t.set("ready",n(now+1.0));}else{add(rt,"alighted",t.num("onboard"));t.set("onboard",n(0.0));t.set("status",text("finished"));}}}continue;}if t.get("status").text()=="finished"||now<t.num("ready"){continue;}let ix=if t.num("dir")==1.0{t.num("index")}else{t.num("index")-1.0}as usize;let id=t.get("trackIds").array().get(ix).cloned().unwrap_or(V::Missing);let tr=legacy::track(s,&id);if !tr.truth(){t.set("status",text("finished"));continue;}let from=t.get("stops").array()[t.num("index")as usize].clone();let to=t.get("stops").array()[(t.num("index")+t.num("dir"))as usize].clone();let direction=if eq(&from,tr.get("a")){1.0}else{-1.0};let block=format!("{}|{}",id.text(),direction);if now<rt.get("blocks").zero(&block){if t.get("status").text()!="signal"{add(rt,"waitEvents",1.0);}t.set("status",text("signal"));continue;}board(rt,t);rt.get_mut("events").array_mut().push(obj(&[("minute",n(now)),("track",id.clone()),("direction",n(direction)),("train",t.get("id").clone()),("service",t.get("service").clone())]));if rt.get("events").array().len()>2000{rt.get_mut("events").array_mut().remove(0);}rt.get_mut("blocks").set(&block,n(now+2.0));t.set("status",text("moving"));t.set("departedAt",n(now));t.set("arriveAt",n(now+tr.num("km")/48.0*60.0));t.set("segment",obj(&[("track",id),("from",from),("to",to)]));t.set("progress",n(0.0));}
    rt.set("trains",arr(trains.into_iter().filter(|t|t.get("status").text()!="finished").collect()));
}
fn advance(rt:&mut V,s:&V,minutes:f64){let mut left=minutes;while left>1e-9{let dt=left.min(0.1);tick(rt,s,dt);left-=dt;}}
pub(super) fn run(action:&str,s:&V,a:&V)->V{match action{"operationsCreate"=>create(s,a.get("metrics"),if has(a,"start"){a.num("start")}else{420.0}),"operationsGroups"=>groups(s,a.get("metrics")),"operationsOpen"=>boolean(open(a.get("line"),a.num("minute"))),"operationsAdvance"=>{let mut rt=a.get("runtime").clone();let minutes=a.num("minutes");if !minutes.is_finite()||!(0.0..=1440.0).contains(&minutes){return obj(&[("error",text("Invalid operation interval"))]);}advance(&mut rt,s,minutes);rt},"operationsSummary"=>{let rt=a.get("runtime");let ts=rt.get("trains").array();let waiting=rt.get("queues").entries().iter().flat_map(|(_,q)|q.entries().iter().map(|(_,v)|v.n())).sum();obj(&[("active",n(ts.len()as f64)),("moving",n(ts.iter().filter(|t|t.get("status").text()=="moving").count()as f64)),("waiting",n(waiting)),("onboard",n(ts.iter().map(|t|t.num("onboard")).sum())),("boarded",rt.get("boarded").clone()),("alighted",rt.get("alighted").clone()),("generated",rt.get("generated").clone()),("signal",n(ts.iter().filter(|t|t.get("status").text()=="signal").count()as f64))])},_=>obj(&[("error",text("UNKNOWN_LEGACY_OPERATIONS_QUERY"))])}}

#[derive(Default)]
pub(super) struct Owner{next:u64,arenas:std::collections::HashMap<u64,(V,V)>}
impl Owner{
 pub(super) fn request(&mut self,input:&V,forecasts:&crate::forecast_session::ForecastOwner)->V{let action=input.get("action").text();let a=input.get("args");if action=="groups"{return if a.get("catalog").truth(){forecasts.legacy_groups(a.get("state"),a.num("catalog")as u64)}else{groups(a.get("state"),a.get("metrics"))};}
  if action=="create"||action=="restore"{let state=a.get("state").clone();let rt=if action=="create"{{let start=if has(a,"start"){a.num("start")}else{420.0};if a.get("catalog").truth(){let rows=forecasts.legacy_groups(&state,a.num("catalog")as u64);if rows.get("error").truth(){return rows;}create_groups(&state,rows,start)}else{create(&state,a.get("metrics"),start)}}}else{a.get("runtime").clone()};if !rt.num("minute").is_finite()||!matches!(rt.get("trains"),V::Array(_)){return obj(&[("error",text("INVALID_LEGACY_OPERATIONS_CHECKPOINT"))]);}self.next+=1;self.arenas.insert(self.next,(state,rt.clone()));return obj(&[("id",n(self.next as f64)),("runtime",rt)]);}
  let id=a.num("id")as u64;if action=="close"{self.arenas.remove(&id);return V::Null;}let Some((world,rt))=self.arenas.get_mut(&id)else{return obj(&[("error",text("LEGACY_OPERATIONS_EXPIRED"))]);};
  match action{"advance"=>{let minutes=a.num("minutes");if !minutes.is_finite()||!(0.0..=1440.0).contains(&minutes){return obj(&[("error",text("Invalid operation interval"))]);}if a.get("state").truth(){*world=a.get("state").clone();}advance(rt,world,minutes);obj(&[("runtime",rt.clone())])},"snapshot"=>obj(&[("runtime",rt.clone())]),"summary"=>run("operationsSummary",world,&obj(&[("runtime",rt.clone())])),"command"=>{let command=a.get("command");let out=legacy::run(&obj(&[("state",world.clone()),("action",command.get("action").clone()),("args",command.get("args").clone())]));if !out.get("result").get("error").truth(){*world=out.get("state").clone();}out},_=>obj(&[("error",text("UNKNOWN_LEGACY_OPERATIONS_ACTION"))])}
 }
}
